import {favoriteEntries,ownedFavorite,favoriteField,favoriteGrid} from './favorite-picker.mjs';
import {TRAINER_CATALOG} from './trainer-catalog.mjs';
export const AVATARS=[['red-gen3','Rouge'],['leaf-gen3','Vert'],['brendan-gen3','Explorateur'],['may-gen3','Exploratrice'],['lucas','Aurore boréale'],['dawn','Étoile du matin'],['ethan','Voyageur'],['lyra','Voyageuse'],['hilbert','Horizon'],['hilda','Aventure'],['nate','Champion'],['rosa','Championne'],['acetrainer','Top Dresseur'],['acetrainerf','Top Dresseuse'],...TRAINER_CATALOG];
const avatarIds=new Set(AVATARS.map(a=>a[0]));
export function normalizePlayer(raw){return{name:String(raw?.name||'Dresseur').trim().slice(0,20)||'Dresseur',avatar:avatarIds.has(raw?.avatar)?raw.avatar:'red-gen3',favorite:/^\d{1,4}s?$/.test(String(raw?.favorite))?String(raw.favorite):'25'}}
export const trainerSrc=id=>'assets/trainers/'+(avatarIds.has(id)?id.startsWith('trainer-')?'catalog/'+id:id:'red-gen3')+'.png';
export function playerStats(s){return{species:new Set(s.roster.map(k=>parseInt(k))).size,shiny:s.roster.filter(k=>k.endsWith('s')).length,tower:Math.min(50,s.floor-1),den:s.raids?.wins||0,survivalRuns:s.runs,survivalKills:s.kills,conquestPlayed:s.conquest?.played||0,conquestWins:s.conquest?.wins||0,clicks:s.afk?.clicks||0,energy:Math.floor(s.afk?.total||0),duels:s.modeStats?.duels||0,duelWins:s.modeStats?.duelWins||0,arena:s.modeStats?.arena||0,arenaWins:s.modeStats?.arenaWins||0}}
const num=n=>Math.floor(n||0).toLocaleString('fr');
export function profilePage(g){const p=normalizePlayer(g.state.player),s=playerStats(g.state),favorite=g.dex[parseInt(p.favorite)]?p.favorite:String(g.state.starter||25);return g.heading('TON AVENTURE, TA SIGNATURE','Ta carte de dresseur','Ton identité et tes exploits à travers PokéWorld.')+`<section class="trainer-pass"><header><span>◒ POKÉWORLD</span><span>CARTE DE DRESSEUR</span></header><div class="trainer-pass-body"><div class="trainer-pass-avatar"><img src="${trainerSrc(p.avatar)}" alt="Ton sprite de dresseur"><span>DRESSEUR POKÉWORLD</span></div><div class="trainer-pass-identity"><span class="eyebrow">LE MONDE T’ATTEND</span><h2>${g.escape(p.name)}</h2><p class="trainer-handle">${g.escape(g.social?.data?.profile?.handle||'Une collection · mille aventures')}</p><div class="trainer-collection"><strong>${num(s.species)}<small>espèces obtenues</small></strong><strong>✧ ${num(s.shiny)}<small>chromatiques</small></strong></div><button class="primary" data-act="profile-edit">Modifier ma carte →</button></div><div class="trainer-pass-favorite"><span class="eyebrow">MON POKÉMON PRÉFÉRÉ</span><canvas width="220" height="180" data-mon="${favorite}" aria-label="${g.escape(g.poke(favorite).name)}"></canvas><h3>${g.escape(g.poke(favorite).name)}${favorite.endsWith('s')?' ✧':''}</h3></div></div><footer><span>TES EXPLOITS · TON HISTOIRE</span><span>POKÉWORLD</span></footer></section><section class="trainer-stat-grid" aria-label="Statistiques des modes">${[
 ['♜','Tour Infernale',num(s.tower)+' / 50','étages vaincus'],['◈','L’Antre',num(s.den),'raids remportés'],['✦','Survie',num(s.survivalRuns),'expéditions · '+num(s.survivalKills)+' Pokémon vaincus'],['⚑','Conquête',num(s.conquestWins)+' / '+num(s.conquestPlayed),'victoires / campagnes'],['◒','Pokéclick',num(s.clicks),'clics · '+num(s.energy)+' énergie produite'],['⚔','Combats classiques',num(s.duelWins)+' / '+num(s.duels),'victoires / combats suivis'],['◇','Arène 2D',num(s.arenaWins)+' / '+num(s.arena),'victoires / combats suivis']
 ].map(([i,name,n,label])=>`<article><span>${i}</span><h3>${name}</h3><strong>${n}</strong><small>${label}</small></article>`).join('')}</section><p class="trainer-stat-note">Les statistiques de duels et d’arène sont suivies à partir de cette mise à jour.</p>${g.profileEditing?profileEditor(g):''}`}
function draft(g){const d=g.profileDraft||g.state.player;return normalizePlayer({...d,name:document.querySelector('#player-name')?.value??d.name,favorite:document.querySelector('#profile-favorite')?.value??d.favorite})}
function profileEditor(g){const p=g.profileDraft||normalizePlayer(g.state.player),q=(g.avatarQuery||'').toLowerCase(),matches=AVATARS.filter(([id,label])=>(label+' '+id).toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(matches.length/42));g.avatarPage=Math.max(0,Math.min(g.avatarPage||0,pages-1));return `<section class="profile-editor panel"><div class="section-title"><div><span class="eyebrow">PERSONNALISE TON IDENTITÉ</span><h2>Modifier ma carte</h2></div><button data-act="profile-cancel">Annuler</button></div><div class="profile-fields"><label>Nom de dresseur<input id="player-name" maxlength="20" value="${g.escape(p.name)}" autocomplete="nickname"></label>${favoriteField(g,p)}</div>${favoriteGrid(g,p)}<div class="avatar-toolbar"><h3>Choisis ton sprite · ${AVATARS.length} disponibles</h3><input id="avatar-search" placeholder="Rechercher un dresseur ou une génération…" value="${g.escape(g.avatarQuery||'')}" aria-label="Rechercher un sprite"></div><div class="avatar-picker full-avatar-picker">${matches.slice(g.avatarPage*42,(g.avatarPage+1)*42).map(([id,label])=>`<button class="${id===p.avatar?'selected':''}" data-act="profile-avatar" data-avatar="${id}" title="${g.escape(label)}" aria-label="${g.escape(label)}" aria-pressed="${id===p.avatar}"><img loading="lazy" src="${trainerSrc(id)}" alt=""></button>`).join('')}</div><div class="avatar-pages"><button data-act="avatar-page" data-page="${g.avatarPage-1}" ${!g.avatarPage?'disabled':''}>← Précédents</button><span>${g.avatarPage+1} / ${pages}</span><button data-act="avatar-page" data-page="${g.avatarPage+1}" ${g.avatarPage>=pages-1?'disabled':''}>Suivants →</button></div><button class="primary" data-act="profile-save">Enregistrer ma carte</button><p class="muted">Le nom et le sprite sont visibles par tes amis et tes adversaires. Chaque compte possède aussi un identifiant unique dans le carnet.</p></section>`}
export async function profileAction(g,act,d){
 if(act==='profile-edit'){g.profileDraft=normalizePlayer(g.state.player);g.profileDraft.favorite=ownedFavorite(g,g.profileDraft.favorite);g.favoritePickerOpen=true;g.favoriteQuery='';g.favoritePage=0;g.profileEditing=true;g.avatarPage=0;g.render();g.root.querySelector('.profile-editor')?.scrollIntoView({behavior:'instant',block:'start'});return}
 if(act==='profile-cancel'){g.profileEditing=false;g.profileDraft=null;g.render();return}
 g.profileDraft=draft(g);
 if(act==='favorite-toggle'){g.favoritePickerOpen=!g.favoritePickerOpen;g.render();return}
 if(act==='favorite-page'){g.favoritePage=+d.page;g.render();return}
 if(act==='favorite-select'){if(!favoriteEntries(g).some(e=>e.keys.includes(d.key)))return;g.profileDraft.favorite=d.key;g.render();return}
 if(act==='profile-avatar'){g.profileDraft.avatar=d.avatar;g.render();return}
 if(act==='avatar-page'){g.avatarPage=+d.page;g.render();return}
 if(act==='profile-save'){if(!favoriteEntries(g).some(e=>e.keys.includes(g.profileDraft.favorite)))return g.toast('Choisis un Pokémon obtenu dans ta collection.');g.state.player=normalizePlayer(g.profileDraft);g.profileDraft=null;g.profileEditing=false;g.save();g.render();window.scrollTo(0,0);g.toast('Carte de dresseur enregistrée.');await g.social.saveProfile();return}
}
export function bindProfileSearch(g){const search=g.root.querySelector('#favorite-search');if(search)search.addEventListener('input',()=>{g.profileDraft=draft(g);g.favoriteQuery=search.value;g.favoritePage=0;clearTimeout(g.favoriteSearchTimer);g.favoriteSearchTimer=setTimeout(()=>{g.render();const next=g.root.querySelector('#favorite-search');next?.focus();next?.setSelectionRange(next.value.length,next.value.length)},160)});const input=g.root.querySelector('#avatar-search');if(input)input.addEventListener('input',()=>{g.profileDraft=draft(g);g.avatarQuery=input.value;g.avatarPage=0;clearTimeout(g.avatarSearchTimer);g.avatarSearchTimer=setTimeout(()=>{g.render();const next=g.root.querySelector('#avatar-search');next?.focus();next?.setSelectionRange(next.value.length,next.value.length)},160)})}
